from pathlib import Path

root = Path("project")

data_path = root / "src/main/java/com/mcmoddev/golems/data/behavior/data/ShootBehaviorData.java"
text = data_path.read_text()

text = text.replace(
    "import net.minecraft.nbt.CompoundTag;\nimport net.minecraft.world.entity.ai.goal.MeleeAttackGoal;",
    "import net.minecraft.nbt.CompoundTag;\nimport net.minecraft.world.entity.LivingEntity;\nimport net.minecraft.world.entity.ai.goal.MeleeAttackGoal;\nimport org.jetbrains.annotations.Nullable;"
)

old = """\tprivate final RangedAttackGoal rangedAttackGoal;\n\tprivate final MeleeAttackGoal meleeAttackGoal;\n"""
new = """\tprivate final RangedAttackGoal rangedAttackGoal;\n\tprivate final MeleeAttackGoal meleeAttackGoal;\n\n\t// Per-golem combat timing for the dispenser golem's ranged fallback.\n\tprivate @Nullable LivingEntity trackedTarget;\n\tprivate long targetAcquiredGameTime = Long.MIN_VALUE;\n\tprivate long lastSuccessfulMeleeHitGameTime = Long.MIN_VALUE;\n\tprivate long lastRangedShotGameTime = Long.MIN_VALUE;\n"""
if old not in text:
    raise SystemExit("ShootBehaviorData field insertion point not found")
text = text.replace(old, new, 1)

marker = """\tpublic int getAmmo() {\n\t\treturn this.entity.getAmmo();\n\t}\n\n\t//// NBT ////\n"""
insert = """\tpublic int getAmmo() {\n\t\treturn this.entity.getAmmo();\n\t}\n\n\t//// DISPENSER RANGED FALLBACK ////\n\n\tpublic void trackTarget(final @Nullable LivingEntity target, final long gameTime) {\n\t\tif (target != this.trackedTarget) {\n\t\t\tthis.trackedTarget = target;\n\t\t\tthis.targetAcquiredGameTime = target == null ? Long.MIN_VALUE : gameTime;\n\t\t\t// A new target must independently fail to receive a melee hit for ten seconds.\n\t\t\tthis.lastSuccessfulMeleeHitGameTime = Long.MIN_VALUE;\n\t\t\tthis.lastRangedShotGameTime = Long.MIN_VALUE;\n\t\t}\n\t}\n\n\t/**\n\t * Returns true once the current target has gone the requested time without the\n\t * golem landing a successful melee attack. Merely being inside melee reach does\n\t * not count as a hit and therefore cannot suppress the ranged fallback.\n\t */\n\tpublic boolean hasGoneWithoutSuccessfulMeleeHitFor(final long gameTime, final long ticks) {\n\t\tif (this.trackedTarget == null || this.targetAcquiredGameTime == Long.MIN_VALUE) {\n\t\t\treturn false;\n\t\t}\n\t\tfinal long baseline = this.lastSuccessfulMeleeHitGameTime == Long.MIN_VALUE\n\t\t\t\t? this.targetAcquiredGameTime\n\t\t\t\t: this.lastSuccessfulMeleeHitGameTime;\n\t\treturn gameTime - baseline >= ticks;\n\t}\n\n\tpublic void markSuccessfulMeleeHit(final long gameTime) {\n\t\tthis.lastSuccessfulMeleeHitGameTime = gameTime;\n\t}\n\n\tpublic void markRangedShot(final long gameTime) {\n\t\tthis.lastRangedShotGameTime = gameTime;\n\t}\n\n\tpublic boolean hasRangedShotCooldownElapsed(final long gameTime, final long ticks) {\n\t\treturn this.lastRangedShotGameTime == Long.MIN_VALUE\n\t\t\t\t|| gameTime - this.lastRangedShotGameTime >= ticks;\n\t}\n\n\t//// NBT ////\n"""
if marker not in text:
    raise SystemExit("ShootBehaviorData getter/NBT insertion point not found")
text = text.replace(marker, insert, 1)
data_path.write_text(text)

shoot_path = root / "src/main/java/com/mcmoddev/golems/data/behavior/ShootArrowsBehavior.java"
text = shoot_path.read_text()

# ProjectileItem is Minecraft's generic API for items that know how to become a
# projectile from an entity/dispenser. Fire charges are a special vanilla dispenser
# case, so they are handled explicitly with SmallFireball.
text = text.replace(
    "import net.minecraft.world.entity.projectile.arrow.AbstractArrow;\nimport net.minecraft.world.entity.projectile.ProjectileUtil;",
    "import net.minecraft.world.entity.projectile.Projectile;\nimport net.minecraft.world.entity.projectile.ProjectileUtil;\nimport net.minecraft.world.entity.projectile.arrow.AbstractArrow;\nimport net.minecraft.world.entity.projectile.hurtingprojectile.SmallFireball;"
)
text = text.replace(
    "import net.minecraft.world.item.ArrowItem;\nimport net.minecraft.world.item.ItemStack;",
    "import net.minecraft.world.item.ArrowItem;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraft.world.item.ProjectileItem;"
)

old = """\t/** The amount of damage dealt by arrows **/\n\tprivate final double damage;\n"""
new = """\t/** The amount of damage dealt by arrows **/\n\tprivate final double damage;\n\n\t// Warden-inspired switch condition: if the golem has failed to LAND a melee\n\t// hit on the same target for ten seconds, ranged fire becomes available.\n\tprivate static final long MELEE_FAILURE_FALLBACK_TICKS = 10L * 20L;\n\tprivate static final double WARDEN_HORIZONTAL_RANGE_SQR = 15.0D * 15.0D;\n\tprivate static final double WARDEN_VERTICAL_RANGE = 20.0D;\n\tprivate static final double RANGED_DISTANCE_FACTOR_RANGE = 32.0D;\n"""
if old not in text:
    raise SystemExit("ShootArrowsBehavior damage field insertion point not found")
text = text.replace(old, new, 1)

old_attack = """\t@Override\n\tprotected boolean performRangedAttack(IExtraGolem entity, LivingEntity target, float distanceFactor) {\n\t\tfinal Mob mob = entity.asMob();\n\t\tItemStack itemstack = consume() ? findFirst(entity.getInventory(), this::isAmmo) : new ItemStack(Items.ARROW);\n\t\tif(itemstack.isEmpty()) {\n\t\t\treturn false;\n\t\t}\n\t\t// raytrace to ensure no other creatures are in the way\n\t\tfinal Vec3 start = mob.position().add(0, mob.getBbHeight() * 0.55F, 0);\n\t\tfinal Vec3 end = target.position().add(0, mob.getBbHeight() * 0.5F, 0);\n\t\tif(!hasClearPath(entity, start, end)) {\n\t\t\treturn false;\n\t\t}\n\t\t// make an arrow out of the inventory\n\t\tAbstractArrow arrow = ProjectileUtil.getMobArrow(mob, itemstack, distanceFactor, null);\n\t\tarrow.setPos(mob.getX(), mob.getY() + mob.getBbHeight() * 0.55F, mob.getZ());\n\t\tdouble d0 = target.getX() - mob.getX();\n\t\tdouble d1 = target.getY(1.0D / 3.0D) - arrow.getY();\n\t\tdouble d2 = target.getZ() - mob.getZ();\n\t\tdouble d3 = Math.sqrt(d0 * d0 + d2 * d2);\n\t\t// set location and attributes\n\t\tarrow.shoot(d0, d1 + d3 * (double) 0.2F, d2, 1.6F, (float) (14 - mob.level().getDifficulty().getId() * 4));\n\t\tarrow.pickup = AbstractArrow.Pickup.ALLOWED;\n\t\tarrow.setOwner(mob);\n\t\tarrow.setBaseDamage(this.getDamage(entity));\n\t\t// play sound and add arrow to world\n\t\tmob.level().addFreshEntity(arrow);\n\t\t// play sound\n\t\tmob.playSound(SoundEvents.ARROW_SHOOT, 1.0F, 1.0F / (mob.getRandom().nextFloat() * 0.4F + 0.8F));\n\t\t// update itemstack\n\t\titemstack.shrink(1);\n\t\treturn true;\n\t}\n\n\t@Override\n\tpublic boolean isAmmo(ItemStack itemStack) {\n\t\treturn consume() && itemStack.getItem() instanceof ArrowItem;\n\t}\n"""

new_attack = """\t@Override\n\tprotected boolean performRangedAttack(IExtraGolem entity, LivingEntity target, float distanceFactor) {\n\t\tfinal Mob mob = entity.asMob();\n\t\tfinal ItemStack itemstack = consume() ? findFirst(entity.getInventory(), this::isAmmo) : new ItemStack(Items.ARROW);\n\t\tif (itemstack.isEmpty()) {\n\t\t\treturn false;\n\t\t}\n\n\t\t// Do not shoot through bystanders. This remains stricter than the Warden's\n\t\t// sonic boom because these are real projectiles with collision.\n\t\tfinal Vec3 start = mob.position().add(0, mob.getBbHeight() * 0.55F, 0);\n\t\tfinal Vec3 end = target.position().add(0, target.getBbHeight() * 0.5F, 0);\n\t\tif (!hasClearPath(entity, start, end)) {\n\t\t\treturn false;\n\t\t}\n\n\t\tfinal boolean fired;\n\t\tif (itemstack.getItem() instanceof ArrowItem) {\n\t\t\tfired = shootArrow(entity, target, itemstack, distanceFactor, start);\n\t\t} else if (itemstack.is(Items.FIRE_CHARGE)) {\n\t\t\tfired = shootFireCharge(entity, target, start);\n\t\t} else if (itemstack.getItem() instanceof ProjectileItem projectileItem && !itemstack.is(Items.ENDER_PEARL)) {\n\t\t\tfired = shootProjectileItem(entity, target, itemstack, projectileItem, start);\n\t\t} else {\n\t\t\tfired = false;\n\t\t}\n\n\t\tif (fired && consume()) {\n\t\t\titemstack.shrink(1);\n\t\t}\n\t\treturn fired;\n\t}\n\n\tprivate boolean shootArrow(final IExtraGolem entity, final LivingEntity target, final ItemStack itemstack,\n\t\t\tfinal float distanceFactor, final Vec3 start) {\n\t\tfinal Mob mob = entity.asMob();\n\t\tfinal AbstractArrow arrow = ProjectileUtil.getMobArrow(mob, itemstack, distanceFactor, null);\n\t\tarrow.setPos(start.x, start.y, start.z);\n\t\tfinal double d0 = target.getX() - start.x;\n\t\tfinal double d1 = target.getY(1.0D / 3.0D) - start.y;\n\t\tfinal double d2 = target.getZ() - start.z;\n\t\tfinal double d3 = Math.sqrt(d0 * d0 + d2 * d2);\n\t\tarrow.shoot(d0, d1 + d3 * 0.2D, d2, 1.6F, (float) (14 - mob.level().getDifficulty().getId() * 4));\n\t\tarrow.pickup = AbstractArrow.Pickup.ALLOWED;\n\t\tarrow.setOwner(mob);\n\t\tarrow.setBaseDamage(this.getDamage(entity));\n\t\tmob.level().addFreshEntity(arrow);\n\t\tmob.playSound(SoundEvents.ARROW_SHOOT, 1.0F, 1.0F / (mob.getRandom().nextFloat() * 0.4F + 0.8F));\n\t\treturn true;\n\t}\n\n\tprivate boolean shootFireCharge(final IExtraGolem entity, final LivingEntity target, final Vec3 start) {\n\t\tfinal Mob mob = entity.asMob();\n\t\tfinal SmallFireball fireball = new SmallFireball(mob.level(), mob, Vec3.ZERO);\n\t\tfireball.setPos(start.x, start.y, start.z);\n\t\tfinal double dx = target.getX() - start.x;\n\t\tfinal double dy = target.getEyeY() - 1.1D - start.y;\n\t\tfinal double dz = target.getZ() - start.z;\n\t\tfinal double arc = Math.sqrt(dx * dx + dz * dz) * 0.2D;\n\t\tfireball.shoot(dx, dy + arc, dz, 1.6F, 8.0F);\n\t\tmob.level().addFreshEntity(fireball);\n\t\tmob.playSound(SoundEvents.FIRECHARGE_USE, 1.0F, 0.8F + mob.getRandom().nextFloat() * 0.4F);\n\t\treturn true;\n\t}\n\n\tprivate boolean shootProjectileItem(final IExtraGolem entity, final LivingEntity target, final ItemStack itemstack,\n\t\t\tfinal ProjectileItem projectileItem, final Vec3 start) {\n\t\tfinal Mob mob = entity.asMob();\n\t\t// ProjectileItem is the vanilla abstraction used by projectile-capable items\n\t\t// for entity/dispenser launches. Use a one-item copy so creation cannot consume\n\t\t// or mutate the golem's real inventory stack before a successful shot.\n\t\tfinal Projectile projectile = projectileItem.asProjectile(mob.level(), start, itemstack.copyWithCount(1), mob.getDirection());\n\t\tprojectile.setOwner(mob);\n\t\tprojectile.setPos(start.x, start.y, start.z);\n\t\tfinal double dx = target.getX() - start.x;\n\t\tfinal double dy = target.getEyeY() - 1.1D - start.y;\n\t\tfinal double dz = target.getZ() - start.z;\n\t\tfinal double arc = Math.sqrt(dx * dx + dz * dz) * 0.2D;\n\t\tprojectileItem.shoot(projectile, dx, dy + arc, dz, 1.6F,\n\t\t\t\t(float) (12 - mob.level().getDifficulty().getId() * 2));\n\t\tmob.level().addFreshEntity(projectile);\n\t\tmob.playSound(SoundEvents.ARROW_SHOOT, 1.0F, 0.9F + mob.getRandom().nextFloat() * 0.2F);\n\t\treturn true;\n\t}\n\n\t@Override\n\tpublic boolean isAmmo(ItemStack itemStack) {\n\t\tif (!consume()) {\n\t\t\treturn false;\n\t\t}\n\t\tif (itemStack.getItem() instanceof ArrowItem || itemStack.is(Items.FIRE_CHARGE)) {\n\t\t\treturn true;\n\t\t}\n\t\t// Accept Minecraft's dispenser/entity projectile items broadly, but exclude\n\t\t// ender pearls because their owner-teleport semantics would teleport the golem.\n\t\treturn itemStack.getItem() instanceof ProjectileItem && !itemStack.is(Items.ENDER_PEARL);\n\t}\n"""

if old_attack not in text:
    raise SystemExit("ShootArrowsBehavior ranged attack block not found")
text = text.replace(old_attack, new_attack, 1)

old_methods = """\t@Override\n\tpublic void onAttachData(IExtraGolem entity) {\n\t\tfinal RangedAttackGoal rangedGoal = new RangedAttackGoal(entity.asMob(), 1.0D, getAttackInterval(), 32.0F);\n\t\tfinal MeleeAttackGoal meleeGoal = new MeleeAttackGoal(entity.asMob(), 1.0D, true);\n\t\tentity.attachBehaviorData(new ShootBehaviorData(entity, rangedGoal, meleeGoal));\n\t}\n\n\t@Override\n\tpublic List<Component> createDescriptions(RegistryAccess registryAccess) {\n"""

new_methods = """\t@Override\n\tpublic void onAttachData(IExtraGolem entity) {\n\t\t// The melee goal owns movement at all times, so the golem keeps closing distance\n\t\t// while a ranged shot is layered on top of the chase.\n\t\tfinal RangedAttackGoal rangedGoal = new RangedAttackGoal(entity.asMob(), 1.0D, getAttackInterval(), 32.0F);\n\t\tfinal MeleeAttackGoal meleeGoal = new MeleeAttackGoal(entity.asMob(), 1.0D, true);\n\t\tentity.attachBehaviorData(new ShootBehaviorData(entity, rangedGoal, meleeGoal));\n\t}\n\n\t@Override\n\tprotected void updateCombatTask(final IExtraGolem entity, final boolean forceMelee) {\n\t\tfinal Mob mob = entity.asMob();\n\t\tgetShootData(entity).ifPresent(data -> {\n\t\t\tmob.goalSelector.removeGoal(data.getRangedGoal());\n\t\t\tmob.goalSelector.removeGoal(data.getMeleeGoal());\n\t\t\tmob.goalSelector.addGoal(0, data.getMeleeGoal());\n\t\t});\n\t}\n\n\t@Override\n\tpublic void onTarget(final IExtraGolem entity, final LivingEntity target) {\n\t\tsuper.onTarget(entity, target);\n\t\tfinal long gameTime = entity.asMob().level().getGameTime();\n\t\tgetShootData(entity).ifPresent(data -> data.trackTarget(target, gameTime));\n\t}\n\n\t@Override\n\tpublic void onAttack(final IExtraGolem entity, final net.minecraft.world.entity.Entity target) {\n\t\t// Only an ACTUAL landed melee attack resets the ten-second fallback timer.\n\t\t// Being geometrically close enough to swing is deliberately not sufficient.\n\t\tfinal long gameTime = entity.asMob().level().getGameTime();\n\t\tgetShootData(entity).ifPresent(data -> data.markSuccessfulMeleeHit(gameTime));\n\t}\n\n\t@Override\n\tpublic void onTick(final IExtraGolem entity) {\n\t\tsuper.onTick(entity);\n\t\tfinal Mob mob = entity.asMob();\n\t\tfinal LivingEntity target = mob.getTarget();\n\t\tfinal long gameTime = mob.level().getGameTime();\n\n\t\tgetShootData(entity).ifPresent(data -> {\n\t\t\tdata.trackTarget(target, gameTime);\n\t\t\tif (target == null || !target.isAlive() || !hasAmmo(entity)) {\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tfinal double dx = target.getX() - mob.getX();\n\t\t\tfinal double dz = target.getZ() - mob.getZ();\n\t\t\tfinal double dy = Math.abs(target.getY() - mob.getY());\n\t\t\tif (dx * dx + dz * dz > WARDEN_HORIZONTAL_RANGE_SQR || dy > WARDEN_VERTICAL_RANGE) {\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\t// The key distinction is successful contact, not nominal melee range. If a\n\t\t\t// target is standing 2 blocks away but is elevated, obstructed, or otherwise\n\t\t\t// impossible to hit, ten seconds without a landed melee hit still unlocks fire.\n\t\t\tif (!data.hasGoneWithoutSuccessfulMeleeHitFor(gameTime, MELEE_FAILURE_FALLBACK_TICKS)) {\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\t// Once fallback is active, restore the Dispenser Golem's original data-driven\n\t\t\t// ranged cadence (28 ticks / 1.4 s in dispenser.json), rather than imposing\n\t\t\t// the Warden's two-second post-attack cooldown.\n\t\t\tif (!data.hasRangedShotCooldownElapsed(gameTime, getAttackInterval())) {\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tif (!mob.getSensing().hasLineOfSight(target)) {\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tfinal float distanceFactor = (float) Math.max(0.1D, Math.min(1.0D,\n\t\t\t\t\tMath.sqrt(mob.distanceToSqr(target)) / RANGED_DISTANCE_FACTOR_RANGE));\n\t\t\tif (performRangedAttack(entity, target, distanceFactor)) {\n\t\t\t\tif (consume()) {\n\t\t\t\t\tentity.getInventory().setChanged();\n\t\t\t\t}\n\t\t\t\tdata.markRangedShot(gameTime);\n\t\t\t}\n\t\t});\n\t}\n\n\t@Override\n\tpublic List<Component> createDescriptions(RegistryAccess registryAccess) {\n"""

if old_methods not in text:
    raise SystemExit("ShootArrowsBehavior method insertion point not found")
text = text.replace(old_methods, new_methods, 1)
shoot_path.write_text(text)

print("Applied pass 13: hit-based 10s dispenser fallback, original 28t shot cadence, continuous pursuit, and expanded projectile ammo")
